(function() {
  const category = $json.category || 'News';
  const ratio    = $json.ratio    || '';

  if (!ratio) {
    throw new Error('Ratio field is required but is empty. Set Ratio to Landscape or Portrait on the Reel Engine record before submitting.');
  }

  const avatarPools = {
    'News': {
      portrait:  ['6c421457cd1043c1bdece3ff4058e274','e6748a486cd6467c99129e6dfd8b1ce3'],
      landscape: ['cc519daab8e84adb9a58cba0d22751ab','f91af36faeee40c99321d90405e49b9f']
    },
    'Education': {
      portrait:  ['beb9498d61204e5f93aa6066731ffac1','22decd2d7ffd416097942dae32deef0d'],
      landscape: ['86e7ca74013a4e49912486b9edfd9545']
    },
    'Product': {
      portrait:  ['9915958faf0e4d9fa1a30a417845bc04','1c89b65735d644d4940910d6bb150e96'],
      landscape: ['02fa6b44002047b8b4ff59d165aa0c91','5170c633017f4ea38f535e1e21840028']
    }
  };

  const orientation = ratio === 'Portrait' ? 'portrait' : 'landscape';
  const pool = (avatarPools[category] || avatarPools['News'])[orientation];
  const avatarId = pool[Math.floor(Math.random() * pool.length)];

  const aspectRatio = ratio === 'Portrait' ? '9:16' : '16:9';

  return JSON.stringify({
    type: 'avatar',
    avatar_id: avatarId,
    script: $json.script,
    voice_id: '19a04c1f886046c7af362c653ef69716',
    title: $json.topic,
    resolution: '1080p',
    aspect_ratio: aspectRatio,
    engine: { type: 'avatar_v' },
    voice_settings: {
      speed: 1.0
    },
    callback_url: 'https://marketing.alfredai.bot/webhook/heygen-callback'
  });
})()
}}

