const response = $input.first().json || {};
const recordData = $('2. Extract + Set Dimensions').first().json;
const videoId = String((response.data && response.data.video_id) || response.video_id || '').trim();
// HG-2: keep the HeyGen error when no video_id comes back, so it can be written to the notes.
let submitError = '';
if (!videoId) {
  const e = response.error || response.message || response;
  submitError = (typeof e === 'string') ? e : (e.message || e.description || JSON.stringify(e));
  submitError = String(submitError).substring(0, 800);
}
return [{ json: { record_id: recordData.record_id, heygen_video_id: videoId, submit_error: submitError, topic: recordData.topic, script: recordData.script, screenshots_needed: recordData.screenshots_needed || '', category: recordData.category, content_type: recordData.content_type, platform: recordData.platform } }];

const fresh = $input.first().json || {};
const d = $('2. Extract + Set Dimensions').first().json;
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = '==============================';
const TAG = 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
let runtime = 'unknown';
try { const s = Date.parse(d.started_at || ''); if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; } } catch (e) {}
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const block = sep + '\n' + TAG + '\nUpdated: ' + stamp + '\nStage: Error - Ratio missing' + '\nRun time: ' + runtime + '\nDetail: Ratio field is empty. Set Ratio to Landscape or Portrait to resume.';
return [{ json: { ...d, reel_notes_final: (base ? base + '\n\n' : '') + block } }];

const fresh = $input.first().json || {};
const d = $('3e. Enough Credits?').first().json;
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = '==============================';
const TAG = 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
let runtime = 'unknown';
try { const s = Date.parse($('2. Extract + Set Dimensions').first().json.started_at || ''); if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; } } catch (e) {}
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const balLine = (d.balance_usd === null || d.balance_usd === undefined) ? ('unknown' + (d.balance_error ? ' (' + d.balance_error + ')' : '')) : ('$' + Number(d.balance_usd).toFixed(2));
const block = sep + '\n' + TAG + '\nUpdated: ' + stamp + '\nStage: Paused - low HeyGen credits' + '\nRun time: ' + runtime + '\nHeyGen wallet balance: ' + balLine + ' (minimum $' + d.min_balance_usd + ')' + '\nAuto reload: ' + (d.auto_reload ? 'on' : 'off') + '\nDetail: Top up the HeyGen API wallet to resume.';
return [{ json: { ...d, reel_notes_final: (base ? base + '\n\n' : '') + block } }];

const fresh = $input.first().json || {};
const d = $('5f. Restore HeyGen Context').first().json;
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = '==============================';
const TAG = 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
let triggered = '';
let runtime = 'unknown';
try {
  const raw = $('2. Extract + Set Dimensions').first().json.started_at || '';
  triggered = raw ? raw.substring(0, 16).replace('T', ' ') : '';
  const s = Date.parse(raw);
  if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; }
} catch (e) {}
const jobId = d.heygen_video_id || '';
const jobUrl = jobId ? 'https://app.heygen.com/videos/' + jobId : '';
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
// HG-2: one line per HeyGen submit. More than one line = the record was rendered more than once.
const NL = String.fromCharCode(10);
const freshHist = (f && typeof f.HeyGen_ID_History === 'string') ? f.HeyGen_ID_History.trim() : '';
const history = (freshHist ? freshHist + NL : '') + new Date().toISOString() + ' | ' + jobId;
const idCount = history.split(NL).filter(l => l.trim()).length;
const block = sep + '\n' + TAG + '\nTriggered: ' + triggered + '\nUpdated: ' + stamp + '\nRun time to submit: ' + runtime + '\nStage: Submitted to HeyGen' + '\nHeyGen Job ID: ' + jobId + (jobUrl ? '\nHeyGen Task URL: ' + jobUrl : '') + (idCount > 1 ? '\nWarning: HeyGen submit number ' + idCount + ' for this record' : '');
return [{ json: { ...d, heygen_id_history: history, heygen_id_count: idCount, reel_notes_final: (base ? base + '\n\n' : '') + block } }];

// HG-2 guardrail: decide from LIVE Airtable data whether this record may go to HeyGen.
const DAILY_VIDEO_CAP = 3; // keep equal to CONTROL > Clients > Daily_Video_Cap (AlfredAI row)
const TZ = 'Asia/Manila';
const READY = 'Ready for Video Generation';
const CAP_LINE = 'Waiting: daily video cap reached';
const NL = String.fromCharCode(10);
const ctx = $('3e. Enough Credits?').first().json;
const flat = r => (r && r.fields && typeof r.fields === 'object') ? { id: r.id, ...r.fields } : (r || {});
const sel = v => (v && typeof v === 'object') ? (v.name || '') : (v || '');
const live = $('3g. Re-read Record Live').all().map(i => flat(i.json)).find(r => r.id === ctx.record_id) || null;
const liveStatus = live ? String(sel(live['Status'])) : '';
const liveId = live ? String(live['HeyGen_Video_ID'] || '').trim() : '';
const liveNotes = (live && typeof live['Reel_Notes'] === 'string') ? live['Reel_Notes'] : '';
// T-44: both approvals are read from the live record.
const approved = !!live && live['Production_Approval'] === true && String(sel(live['Script_Approval'])) === 'Approved';
const today = $now.setZone(TZ).toFormat('yyyy-MM-dd');
const submittedToday = $input.all().map(i => flat(i.json)).filter(r => r.id && r.id !== ctx.record_id).length;

const sep = '==============================';
const TAG = 'AVATAR (WF06)';
const TRG = 'VIDEO TRIGGER (WF06)';
const ORCH = 'PRODUCTION ORCHESTRATOR';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = tag => new RegExp('\\n*' + esc(sep) + '\\n' + esc(tag) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = liveNotes.replace(blockRe(TAG), '').replace(blockRe(TRG), '').trim();
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

// Who moved this reel to Ready for Video Generation? The Production Orchestrator (Manus) logs every move in its own notes block.
// Manus = it logged a move to Ready for Video Generation after the last HeyGen submit. Anything else = set by hand.
const lastOrchMove = notes => {
  const lines = String(notes || '').split(NL);
  let inBlock = false; let curDate = ''; let best = null;
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i].trim();
    if (l === sep) { inBlock = ((lines[i + 1] || '').trim() === ORCH); curDate = ''; continue; }
    if (!inBlock) continue;
    if (l.length === 10 && l[4] === '-' && l[7] === '-') { curDate = l; continue; }
    if (curDate && l.includes('-> ' + READY)) {
      const hm = l.slice(0, 5);
      const zone = (l.slice(6).split(' ')[0] || TZ);
      let d = DateTime.fromISO(curDate + 'T' + hm, { zone });
      if (!d.isValid) d = DateTime.fromISO(curDate + 'T' + hm, { zone: TZ });
      if (d.isValid && (!best || d > best)) best = d;
    }
  }
  return best;
};
const orchAt = lastOrchMove(liveNotes);
const prevSubmit = live && live['HeyGen_Submitted_At'] ? DateTime.fromISO(String(live['HeyGen_Submitted_At'])) : null;
const byManus = !!(orchAt && (!prevSubmit || !prevSubmit.isValid || orchAt > prevSubmit));
const movedBy = byManus ? 'Production Orchestrator (Manus), ' + orchAt.setZone(TZ).toFormat('yyyy-MM-dd HH:mm') + ' ' + TZ : 'Manual (set by hand, no Production Orchestrator entry for this move)';
const trgBlock = [sep, TRG, 'Updated: ' + stamp, 'Moved to ' + READY + ' by: ' + movedBy].join(NL);
const mk = lines => (base ? base + NL + NL : '') + trgBlock + NL + NL + sep + NL + TAG + NL + lines.join(NL);

let action = 'submit';
let reason = '';
let notes = '';
if (!live) {
  action = 'skip'; reason = 'Record could not be re-read live';
} else if (liveStatus !== READY) {
  action = 'skip'; reason = 'Live status is ' + liveStatus + ', not ' + READY;
} else if (liveId) {
  action = 'skip'; reason = 'Record already has HeyGen ID ' + liveId;
} else if (!approved) {
  // T-44: not approved. Nothing is submitted, no cap slot is used, Status goes back to Verified.
  action = 'unapproved'; reason = 'Not approved: skipped';
  notes = mk(['Updated: ' + stamp, 'Stage: Skipped', 'Not approved: skipped']);
} else if (submittedToday >= DAILY_VIDEO_CAP) {
  reason = CAP_LINE + ' (' + submittedToday + ' of ' + DAILY_VIDEO_CAP + ' on ' + today + ')';
  // Write the waiting note once per day, not on every 1-minute run.
  const alreadyNoted = liveNotes.includes(CAP_LINE) && liveNotes.includes('Cap date: ' + today);
  action = alreadyNoted ? 'skip' : 'cap';
  notes = mk(['Updated: ' + stamp, 'Stage: ' + CAP_LINE, 'Cap date: ' + today, 'Submitted today: ' + submittedToday + ' of ' + DAILY_VIDEO_CAP, 'Detail: Record stays at ' + READY + '. It resumes on its own the next day or when the cap is raised.']);
} else {
  notes = mk(['Updated: ' + stamp, 'Stage: Locked - submitting to HeyGen', 'Daily cap: ' + (submittedToday + 1) + ' of ' + DAILY_VIDEO_CAP]);
}
return [{ json: { ...ctx, gate_action: action, gate_reason: reason, moved_by: byManus ? 'manus' : 'manual', submitted_today: submittedToday, daily_video_cap: DAILY_VIDEO_CAP, locked_at: new Date().toISOString(), reel_notes_final: notes } }];

const fresh = $input.first().json || {};
const d = $('5. Preserve Data + Extract Video ID').first().json;
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const NL = String.fromCharCode(10);
const sep = '==============================';
const TAG = 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const block = [sep, TAG, 'Updated: ' + stamp, 'Stage: Error - HeyGen submit failed', 'HeyGen error: ' + (d.submit_error || 'No video_id in the HeyGen response'), 'Detail: HeyGen returned no video ID, so none was written. Fix the cause, then set Status back to Ready for Video Generation to retry.'].join(NL);
return [{ json: { record_id: d.record_id, reel_notes_final: (base ? base + NL + NL : '') + block } }];
